import{_ as o,c as n,o as t,ag as a}from"./chunks/framework.CPHm90Yq.js";const g=JSON.parse('{"title":"Installing the Argdown commandline tool","description":"","frontmatter":{"title":"Installing the Argdown commandline tool","meta":[{"name":"description","content":"How to install the Argdown commandline tool"}]},"headers":[],"relativePath":"guide/installing-the-commandline-tool.md","filePath":"guide/installing-the-commandline-tool.md"}'),l={name:"guide/installing-the-commandline-tool.md"};function i(r,e,d,s,c,m){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="installing-the-commandline-tool" tabindex="-1">Installing the commandline-tool <a class="header-anchor" href="#installing-the-commandline-tool" aria-label="Permalink to &quot;Installing the commandline-tool&quot;">​</a></h1><p>The Argdown commandline tool is a Node.js program and distributed as a npm package. To install it you first have to install Node.js:</p><ol><li><a href="https://nodejs.org/en/" target="_blank" rel="noreferrer">Download Node.js</a> and install it manually or use a <a href="https://nodejs.org/en/download/package-manager/" target="_blank" rel="noreferrer">package manager</a> to install it. You need at least Node 8.0.0, so if you already have node installed, please check its version (&#39;node --version&#39;) and update it if needed. Npm is node&#39;s package manager and comes already installed with Node.js so you can now use it.</li><li>Run <code>npm install -g @argdown/cli</code> to install the comandline tool globally.</li><li>You can now run <code>argdown --help</code> in the commandline to get further help on using the commandline tool. The tool consists of several commands for exporting Argdown documents into other document formats. For example <code>argdown map</code> will export any Argdown files in the current directory as svg files that are saved in the &quot;svg&quot; folder. You can get help for the options of each command by using the <code>--help</code> parameter. For example, enter <code>argdown map --help</code> to see all options of the <code>map</code> command.</li></ol><p>Now you can edit Argdown in the editor of your choice. You might want to install our free <a href="https://github.com/argdown/argdown/tree/master/packages/ArgVu" target="_blank" rel="noreferrer">ArgVu</a> font. It comes with Argdown-specific font-ligatures and glyphs.</p><div class="tip custom-block"><p class="custom-block-title">Next step</p><p>If you are new to Argdown, the next step is to follow along with our <a href="/guide/a-first-example.html">first example</a>.</p></div><h2 id="features-of-the-commandline-tool" tabindex="-1">Features of the commandline tool <a class="header-anchor" href="#features-of-the-commandline-tool" aria-label="Permalink to &quot;Features of the commandline tool&quot;">​</a></h2><ul><li>Exports Argdown documents and argument maps to JSON, web component HTML, HTML, DOT, GRAPHML, SVG, PNG or PDF.</li><li>Code linting: Prints syntax error with location information</li><li>You can watch whole folders and automatically execute a command if any Argdown file has changed.</li><li>Extensive configuration options through <code>argdown.config.json</code> or <code>argdown.config.js</code> files.</li><li>Can be extended by custom plugins added in a <code>argdown.config.js</code> file.</li></ul><h2 id="further-help-on-using-the-commandline-tool" tabindex="-1">Further help on using the commandline tool <a class="header-anchor" href="#further-help-on-using-the-commandline-tool" aria-label="Permalink to &quot;Further help on using the commandline tool&quot;">​</a></h2><p>Please read the <a href="https://github.com/argdown/argdown/blob/master/packages/argdown-cli/Readme.md" target="_blank" rel="noreferrer">README</a> of the commandline tool for further information.</p><p>If you run into any issues while installing or running the commandline tool, you can search for existing issues or post a new issue in the <a href="https://github.com/argdown/argdown/issues" target="_blank" rel="noreferrer">Argdown repository</a>.</p>',10)])])}const u=o(l,[["render",i]]);export{g as __pageData,u as default};
